traits <- traits[, apply(traits, 2, var) > 0]
ppca <- phyl.pca(pruned_tree, traits, method = "BM", mode = "corr")
write.csv(ppca$L, "ppca_loadings_seed3.csv")
write.csv(ppca$S, "ppca_scores_seed3.csv")
eig_df <- data.frame(
